      "かくれる(クラウディーナミイロタテハ)や、相手のすくい投げ(カブトムシ)により裏返った自分の虫のみが場にいる場合に縄張りから<装着>を引いた場合、裏向きの虫につけれませんか？: はい。裏向きの虫に＜装着＞で強化カードはつけられません。"
