      "[カイコ]や[武勇の面頬]の効果で、このターン場に出した[レギウスオオツノハナムグリ]が＜王様＞を失いました。[レギウスオオツノハナムグリ]はすぐに攻撃が: はい、可能です。もし攻撃前に何らかの理由で＜王様＞を再度持った状態になった場合、[レギウスオオツノハナムグリ]は攻撃できなくなります。"
