      "コストを支払い[ヨーロッパミヤマクワガタ]を場に出したとき、＜強化甲殻＞を使用して[武勇の面頬]を[ヨーロッパミヤマクワガタ]につけました。 そのあと[武勇の面頬]の効果によって＜: [ヨーロッパミヤマクワガタ]についたままになります。[武勇の面頬]の効果によって＜強化甲殻＞の技を失いますが、処理が終了しているため影響はありません。"
