      "＜月光＞を使ったターン、相手の虫の攻撃でさらに縄張りを引くタイミングがきました。 「このターン縄張りを引かなくてもよい」は、攻撃ごとに選ぶことが: はい、選べます。 「このターン縄張りを引かなくてもよい」はターン中の縄張りを引くタイミングごとに、引くか引かないかを選ぶことができます。"
