      "4/17追記 [電気虫の金砕棒]を対象に[蠱術の贋作]を使用しました。このとき、[電気虫の金砕棒]の「これ場に出たとき、相手の虫を１つ選び、1000のダメージを与えてもよい。」効果: いいえ、発揮しません。 [蠱術の贋作]は他の強化カードの修正値を、つけた虫に与える効果を持ちます。修正値以外は効果の対象になりません。"
